// Compiling a graph file into its folder (src/extension/graph-compile.ts): the generated files never
// write over a file of the user's (docs/audit.md, second pass).
import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { builtinLanguagePacks } from '../../src/core/languages';
import { GraphDocument } from '../../src/core/model';
import { NodeRegistry } from '../../src/core/registry';
import { GraphCompileHost, compileGraphFile } from '../../src/extension/graph-compile';
import { isUsersFile } from '../../src/extension/placement';
import { doc, node, wire } from './helpers';

function folder(files: Record<string, string>): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'vgraph-compile-'));
  for (const [name, content] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), content);
  return dir;
}

function host(): GraphCompileHost & { removed: string[] } {
  const removed: string[] = [];
  return {
    registry: new NodeRegistry(),
    languages: builtinLanguagePacks(),
    write: async (file, text) => fs.writeFileSync(file, text),
    remove: async (file) => {
      removed.push(path.basename(file));
      fs.rmSync(file, { force: true });
    },
    removed
  };
}

const hello = (language: string): GraphDocument => ({ ...doc([node('s', 'core:event.start'), node('p', 'core:console.print', { 'pin:value': 'hi' })], [wire('s', 'execOut', 'p', 'execIn')]), name: 'Hello', language });
const HEADER = '// Generated by Blueprint Visual Scripting from other.vgraph.\n';

describe('generated files and the user\'s', () => {
  test('isUsersFile: a file without the header, or a folder, is the user\'s', () => {
    const dir = folder({ 'mine.ts': 'export {};\n', 'made.ts': HEADER, 'empty.ts': '' });
    fs.mkdirSync(path.join(dir, 'sub'));
    assert.equal(isUsersFile(path.join(dir, 'mine.ts')), true);
    assert.equal(isUsersFile(path.join(dir, 'empty.ts')), true);
    assert.equal(isUsersFile(path.join(dir, 'sub')), true);
    assert.equal(isUsersFile(path.join(dir, 'made.ts')), false);
    assert.equal(isUsersFile(path.join(dir, 'missing.ts')), false);
  });

  test('a compile doesn\'t write over a file of the user\'s, and says so', async () => {
    const mine = 'console.log("mine");\n';
    const dir = folder({ 'hello.vgraph.js': mine });
    const compiled = await compileGraphFile(hello('javascript'), path.join(dir, 'hello.vgraph'), dir, host());
    assert.equal(fs.readFileSync(path.join(dir, 'hello.vgraph.js'), 'utf8'), mine);
    assert.equal(compiled.outputPath, undefined, 'no generated file to run');
    assert.deepEqual(compiled.written, []);
    const error = compiled.diagnostics.find((d) => d.code === 'output-exists');
    assert.equal(error?.severity, 'error');
    assert.match(error!.message, /^hello\.vgraph\.js is already there and wasn't generated from a graph/);
  });

  test('a file generated from a graph is written over, whichever graph (a renamed one\'s)', async () => {
    const dir = folder({ 'hello.vgraph.js': HEADER });
    const compiled = await compileGraphFile(hello('javascript'), path.join(dir, 'hello.vgraph'), dir, host());
    assert.ok(compiled.outputPath);
    assert.match(fs.readFileSync(path.join(dir, 'hello.vgraph.js'), 'utf8'), /from hello\.vgraph\./);
  });

  test('nothing is written when any of the files is the user\'s: C++\'s header', async () => {
    const dir = folder({ 'hello.vgraph.h': '#pragma once\n' });
    const compiled = await compileGraphFile(hello('cpp'), path.join(dir, 'hello.vgraph'), dir, host());
    assert.ok(compiled.diagnostics.some((d) => d.code === 'output-exists' && d.message.startsWith('hello.vgraph.h ')));
    assert.equal(fs.existsSync(path.join(dir, 'hello.vgraph.cpp')), false);
  });

  test('the old language\'s file of the user\'s isn\'t removed either', async () => {
    const dir = folder({ 'hello.vgraph.ts': 'export const mine = 1;\n' });
    const compiler = host();
    const compiled = await compileGraphFile(hello('javascript'), path.join(dir, 'hello.vgraph'), dir, compiler);
    assert.ok(compiled.outputPath);
    assert.deepEqual(compiler.removed, []);
    assert.ok(fs.existsSync(path.join(dir, 'hello.vgraph.ts')));
  });
});
